#include <bits/stdc++.h>
using namespace std;

struct Reader {
    std::istream& in;
    std::string token;
    std::stringstream ss;

    Reader(std::istream& input_stream) : in(input_stream) {}

    std::string readToken() {
        while (ss.rdbuf()->in_avail() == 0) {
            std::string line;
            if (!std::getline(in, line)) {
                return "";
            }
            ss.clear();
            ss.str(line);
        }
        ss >> token;
        return token;
    }

    int readInt() {
        return std::stoi(readToken());
    }

    long long readLong() {
        return std::stoll(readToken());
    }

    double readDouble() {
        return std::stod(readToken());
    }

    std::string readLine() {
        std::string line;
        if (std::getline(in, line)) {
            return line;
        }
        return "";
    }
};

